constructs = sys.argv[1:]
boundaries = [128, 256, 384]
for c in constructs:
    c = c.encode().decode('unicode_escape')
    outs = {}
    for b in boundaries:
        for off in range(-len(c)-3, 4):
            k = b + off - 2
            if k < 0: continue
            src = ('#' + 'a'*k + '\n' + c + ' tail\necho $z\n').encode()
            for mode in ['--transform', '']:
                args = ['/workspace/executable'] + ([mode] if mode else []) + ['']
                r = subprocess.run(args, input=src, capture_output=True)
                out = r.stdout.replace(b'a'*k, b'A') + b'|' + r.stderr.replace(b'a'*k,b'A').split(b'\n')[0] + b'|' + str(r.returncode).encode()
                outs.setdefault(mode, {}).setdefault(out, []).append((b, off))
    for mode, d in outs.items():
        if len(d) > 1:
            print('SENSITIVE:', repr(c), mode)
            for out, locs in d.items():
                print('   ', len(locs), locs[:8], out[:300])
