//! Shellharden reimplementation: a corrective bash syntax highlighter.
//!
//! The input is processed by a stack machine of "situations" (states). Each
//! state inspects the input at the current position, emits colored output and
//! requests a stack transition.

use std::fs::File;
use std::io::{self, Read, Seek, SeekFrom, Write};

// ---------------------------------------------------------------------------
// Colors
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Color {
    None,
    Cmd,
    Var,
    Assign,
    Dq,
    Sq,
    AnsiC,
    Esc,
    Comment,
    Bold,
    Magenta,
    Heredoc,
    Insert,
    Delete,
}

fn color_code(c: Color) -> &'static [u8] {
    match c {
        Color::None => b"\x1b[m",
        Color::Cmd => b"\x1b[0;38;2;192;0;128m",
        Color::Var => b"\x1b[0;38;2;63;127;207m",
        Color::Assign => b"\x1b[0;38;2;0;127;255m",
        Color::Dq => b"\x1b[0;38;2;255;0;0m",
        Color::Sq => b"\x1b[0;38;2;255;204;85m",
        Color::AnsiC => b"\x1b[0;38;2;255;128;0m",
        Color::Esc => b"\x1b[0;1;38;2;255;0;128m",
        Color::Comment => b"\x1b[0;1;3;38;2;120;144;96m",
        Color::Bold => b"\x1b[0;1m",
        Color::Magenta => b"\x1b[0;38;2;192;0;192m",
        Color::Heredoc => b"\x1b[0;38;2;128;32;0m",
        Color::Insert => b"\x1b[0;42m",
        Color::Delete => b"\x1b[0;41m",
    }
}

// ---------------------------------------------------------------------------
// Output writer
// ---------------------------------------------------------------------------

struct Out {
    buf: Vec<u8>,
    cur: Color,
    syntax: bool,
    diff: bool,
    plain: bool,
    changed: bool,
}

impl Out {
    fn new(syntax: bool, diff: bool, plain: bool) -> Out {
        Out { buf: Vec::new(), cur: Color::None, syntax, diff, plain, changed: false }
    }

    fn emit(&mut self, c: Color, bytes: &[u8]) {
        if bytes.is_empty() {
            return;
        }
        if !self.plain && c != self.cur {
            self.buf.extend_from_slice(color_code(c));
            self.cur = c;
        }
        self.buf.extend_from_slice(bytes);
    }

    /// Write original bytes in a syntax color.
    fn put(&mut self, c: Color, bytes: &[u8]) {
        let c = if self.syntax { c } else { Color::None };
        self.emit(c, bytes);
    }

    /// Original bytes that are suggested for deletion.
    fn delete(&mut self, c: Color, bytes: &[u8]) {
        if bytes.is_empty() {
            return;
        }
        self.changed = true;
        if self.plain {
            return;
        }
        if self.diff {
            self.emit(Color::Delete, bytes);
        } else {
            self.put(c, bytes);
        }
    }

    /// Bytes suggested for insertion.
    fn insert(&mut self, bytes: &[u8]) {
        if bytes.is_empty() {
            return;
        }
        self.changed = true;
        if self.plain {
            self.emit(Color::None, bytes);
        } else if self.diff {
            self.emit(Color::Insert, bytes);
        }
    }

    fn finish(&mut self) {
        if !self.plain && self.cur != Color::None {
            self.buf.extend_from_slice(color_code(Color::None));
            self.cur = Color::None;
        }
    }
}

// ---------------------------------------------------------------------------
// Parser states
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum End {
    None,
    Paren,
    Backtick { convert: bool },
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum DollarCtx {
    /// Unquoted word context: expansions get quoted.
    Quote,
    /// Inside a double quote inserted by us.
    Inserted,
    /// Inside a user's double quoted string.
    Dq { at_start: bool },
    /// Context where no quoting is needed (rvalue, test, arith, case ...).
    Plain,
}

#[derive(Debug)]
enum State {
    Normal { end: End, arm: bool },
    Command { end: End, arm: bool, started: bool },
    Args { end: End, arm: bool },
    Rvalue { end: End, arm: bool },
    Array,
    Dq { at_start: bool },
    Inserted,
    Sq,
    AnsiC,
    Test { brackets: u8 },
    Arith { depth: u32 },
    CaseHead { after_ws: bool },
    CaseBody,
    ForVar { end: End, arm: bool },
    ForIn { first: bool },
    Heredoc { delim: Vec<u8>, dash: bool },
    /// Something that was opened but can never be closed (EOF reached).
    Unterminated,
}

enum Act {
    Stay,
    Push(State),
    Pop,
    Replace(State),
    ReplacePush(State, State),
    Err(ParseError),
}

#[derive(Debug)]
enum ParseError {
    Eof,
    Pitfall { start: usize, end: usize },
}

fn is_ident_start(c: u8) -> bool {
    c == b'_' || c.is_ascii_alphabetic()
}

fn is_ident(c: u8) -> bool {
    c == b'_' || c.is_ascii_alphanumeric()
}

fn is_absorbable(c: u8) -> bool {
    match c {
        b'+' | b',' | b'-' | b'.' | b'/' | b':' | b'=' | b'@' | b'[' | b']' | b'^' | b'_' | b'{'
        | b'}' | b'~' => true,
        _ => c.is_ascii_alphanumeric() || c >= 127,
    }
}

fn is_kw_term(c: u8) -> bool {
    c <= 0x20 || matches!(c, b';' | b'&' | b'|' | b'(' | b')' | b'<' | b'>')
}

struct Machine<'a> {
    inp: &'a [u8],
    pos: usize,
    out: Out,
}

impl<'a> Machine<'a> {
    fn at(&self, i: usize) -> Option<u8> {
        self.inp.get(i).copied()
    }

    fn cur(&self) -> u8 {
        self.inp[self.pos]
    }

    fn put_n(&mut self, c: Color, n: usize) {
        let end = (self.pos + n).min(self.inp.len());
        let bytes = &self.inp[self.pos..end];
        self.out.put(c, bytes);
        self.pos = end;
    }

    fn put_to(&mut self, c: Color, end: usize) {
        let bytes = &self.inp[self.pos..end];
        self.out.put(c, bytes);
        self.pos = end;
    }

    fn delete_n(&mut self, c: Color, n: usize) {
        let end = (self.pos + n).min(self.inp.len());
        let bytes = &self.inp[self.pos..end];
        self.out.delete(c, bytes);
        self.pos = end;
    }

    fn insert(&mut self, bytes: &[u8]) {
        self.out.insert(bytes);
    }

    fn is_end(&self, end: End) -> bool {
        match end {
            End::None => false,
            End::Paren => self.cur() == b')',
            End::Backtick { .. } => self.cur() == b'`',
        }
    }

    /// Consume the end trigger of a command list context.
    fn handle_end(&mut self, end: End) {
        match end {
            End::None => {}
            End::Paren => self.put_n(Color::None, 1),
            End::Backtick { convert } => {
                if convert {
                    self.delete_n(Color::None, 1);
                    self.insert(b")");
                } else {
                    self.put_n(Color::None, 1);
                }
            }
        }
    }

    fn escape(&mut self) -> Act {
        if self.pos + 1 < self.inp.len() {
            self.put_n(Color::Esc, 2);
            Act::Stay
        } else {
            self.put_n(Color::Esc, 1);
            Act::Push(State::Unterminated)
        }
    }

    fn comment(&mut self) {
        let mut j = self.pos;
        while j < self.inp.len() && self.inp[j] != b'\n' {
            j += 1;
        }
        self.put_to(Color::Comment, j);
    }

    fn start_dq(&mut self) -> Act {
        self.put_n(Color::Dq, 1);
        Act::Push(State::Dq { at_start: true })
    }

    fn start_sq(&mut self) -> Act {
        self.put_n(Color::Sq, 1);
        Act::Push(State::Sq)
    }

    /// Backtick in a context where no quoting is required.
    fn plain_backtick(&mut self) -> Act {
        self.put_n(Color::None, 1);
        Act::Push(State::Normal { end: End::Backtick { convert: false }, arm: false })
    }

    /// Backtick inside a double quoted string: converted to $( ).
    fn dq_backtick(&mut self) -> Act {
        self.delete_n(Color::None, 1);
        self.insert(b"$(");
        Act::Push(State::Normal { end: End::Backtick { convert: true }, arm: false })
    }

    /// Start of a quoted expansion in an unquoted context.
    fn open_inserted(&mut self) -> Act {
        self.insert(b"\"");
        Act::Push(State::Inserted)
    }

    fn close_inserted(&mut self) -> Act {
        self.insert(b"\"");
        Act::Pop
    }

    // ---------------------------------------------------------------
    // Heredoc
    // ---------------------------------------------------------------

    /// Called with pos at "<<". `color` is the color of the calling state.
    fn heredoc(&mut self, color: Color) -> Act {
        let inp = self.inp;
        let start = self.pos;
        let mut p = start + 2;
        if inp.get(p) == Some(&b'<') {
            self.put_n(color, 3);
            return Act::Stay;
        }
        let mut dash = false;
        if inp.get(p) == Some(&b'-') {
            dash = true;
            p += 1;
        }
        while matches!(inp.get(p), Some(b' ') | Some(b'\t') | Some(b'\n')) {
            p += 1;
        }
        let mut delim: Vec<u8> = Vec::new();
        let fallback = |m: &mut Machine| -> Act {
            m.put_n(color, 2);
            Act::Stay
        };
        loop {
            match inp.get(p) {
                None => return fallback(self),
                Some(b'\\') => match inp.get(p + 1) {
                    None => return fallback(self),
                    Some(b'\n') => p += 2,
                    Some(&c) => {
                        delim.push(c);
                        p += 2;
                    }
                },
                Some(b'"') => {
                    p += 1;
                    loop {
                        match inp.get(p) {
                            None => return fallback(self),
                            Some(b'"') => {
                                p += 1;
                                break;
                            }
                            Some(b'\\') => match inp.get(p + 1) {
                                None => return fallback(self),
                                Some(&c) if c == b'"' || c == b'\\' || c == b'$' || c == b'`' => {
                                    delim.push(c);
                                    p += 2;
                                }
                                Some(b'\n') => p += 2,
                                Some(&c) => {
                                    delim.push(b'\\');
                                    delim.push(c);
                                    p += 2;
                                }
                            },
                            Some(&c) => {
                                delim.push(c);
                                p += 1;
                            }
                        }
                    }
                }
                Some(b'\'') => {
                    p += 1;
                    loop {
                        match inp.get(p) {
                            None => return fallback(self),
                            Some(b'\'') => {
                                p += 1;
                                break;
                            }
                            Some(&c) => {
                                delim.push(c);
                                p += 1;
                            }
                        }
                    }
                }
                Some(b' ') | Some(b'\t') | Some(b'\n') => break,
                Some(&c) => {
                    delim.push(c);
                    p += 1;
                }
            }
        }
        if delim.is_empty() {
            self.put_to(color, p);
            return Act::Stay;
        }
        // Rest of the line belongs to the heredoc.
        let mut q = p;
        while q < inp.len() && inp[q] != b'\n' {
            q += 1;
        }
        if q < inp.len() {
            q += 1;
        }
        self.put_to(Color::Heredoc, q);
        Act::Push(State::Heredoc { delim, dash })
    }

    fn step_heredoc(&mut self, delim: &[u8], dash: bool) -> Act {
        let inp = self.inp;
        let mut q = self.pos;
        while q < inp.len() && inp[q] != b'\n' {
            q += 1;
        }
        let line = &inp[self.pos..q];
        let stripped: &[u8] = if dash {
            let mut k = 0;
            while k < line.len() && line[k] == b'\t' {
                k += 1;
            }
            &line[k..]
        } else {
            line
        };
        if stripped == delim {
            self.put_to(Color::Heredoc, q);
            return Act::Pop;
        }
        if q < inp.len() {
            q += 1;
        }
        self.put_to(Color::Heredoc, q);
        Act::Stay
    }

    // ---------------------------------------------------------------
    // Dollar expansions
    // ---------------------------------------------------------------

    /// Find the extent of a `${...}` whose '{' is at index `brace`.
    /// Returns the index just past the closing '}'.
    fn brace_extent(inp: &[u8], brace: usize) -> Option<usize> {
        let mut i = brace + 1;
        loop {
            match inp.get(i) {
                None => return None,
                Some(b'\\') => i += 2,
                Some(b'$') if inp.get(i + 1) == Some(&b'{') => {
                    i = Self::brace_extent(inp, i + 1)?;
                }
                Some(b'}') => return Some(i + 1),
                Some(_) => i += 1,
            }
        }
    }

    fn is_var_start(c: u8) -> bool {
        is_ident_start(c)
            || c.is_ascii_digit()
            || matches!(c, b'{' | b'(' | b'@' | b'*' | b'-' | b'?' | b'$' | b'!' | b'#')
    }

    /// Called with pos at '$'. `color` is the color of the calling state.
    fn dollar(&mut self, ctx: DollarCtx, color: Color) -> Act {
        let inp = self.inp;
        let p = self.pos;
        let next = inp.get(p + 1).copied();
        if ctx == DollarCtx::Inserted {
            match next {
                Some(c) if Self::is_var_start(c) => {}
                _ => return self.close_inserted(),
            }
        }
        match next {
            None => {
                self.put_n(color, 1);
                Act::Stay
            }
            Some(b'\'') => {
                if let DollarCtx::Dq { .. } = ctx {
                    self.put_n(color, 1);
                    Act::Stay
                } else {
                    self.put_n(Color::AnsiC, 2);
                    Act::Push(State::AnsiC)
                }
            }
            Some(b'"') => {
                self.put_n(color, 1);
                Act::Stay
            }
            Some(b'(') => {
                if inp.get(p + 2) == Some(&b'(') {
                    self.put_n(Color::Magenta, 3);
                    Act::Push(State::Arith { depth: 2 })
                } else if ctx == DollarCtx::Quote {
                    self.open_inserted()
                } else {
                    self.put_n(Color::None, 2);
                    Act::Push(State::Normal { end: End::Paren, arm: false })
                }
            }
            Some(b'{') => self.dollar_brace(ctx, p),
            Some(c) if is_ident_start(c) => self.dollar_ident(ctx, p),
            Some(c) if c.is_ascii_digit() => {
                let mut e = p + 1;
                while e < inp.len() && inp[e].is_ascii_digit() {
                    e += 1;
                }
                if e - (p + 1) >= 2 {
                    return Act::Err(ParseError::Pitfall { start: p, end: e });
                }
                if ctx == DollarCtx::Quote {
                    self.open_inserted()
                } else {
                    self.put_n(Color::Var, 2);
                    Act::Stay
                }
            }
            Some(b'@') | Some(b'-') => {
                if ctx == DollarCtx::Quote {
                    self.open_inserted()
                } else {
                    self.put_n(Color::Var, 2);
                    Act::Stay
                }
            }
            Some(b'*') => match ctx {
                DollarCtx::Quote => {
                    self.insert(b"\"");
                    self.put_n(Color::Var, 1);
                    self.delete_n(Color::Var, 1);
                    self.insert(b"@");
                    self.insert(b"\"");
                    Act::Stay
                }
                DollarCtx::Inserted => {
                    self.put_n(Color::Var, 2);
                    self.close_inserted()
                }
                _ => {
                    self.put_n(Color::Var, 2);
                    Act::Stay
                }
            },
            Some(b'?') | Some(b'$') | Some(b'!') | Some(b'#') => {
                self.put_n(Color::Var, 2);
                Act::Stay
            }
            Some(_) => {
                self.put_n(color, 1);
                Act::Stay
            }
        }
    }

    fn dollar_ident(&mut self, ctx: DollarCtx, p: usize) -> Act {
        let inp = self.inp;
        let mut e = p + 1;
        while e < inp.len() && is_ident(inp[e]) {
            e += 1;
        }
        match ctx {
            DollarCtx::Quote => self.open_inserted(),
            DollarCtx::Inserted => {
                let braces = match inp.get(e) {
                    None => true,
                    Some(b'"') => match inp.get(e + 1) {
                        None => true,
                        Some(&d) => is_ident(d),
                    },
                    _ => false,
                };
                if braces {
                    self.put_n(Color::Var, 1);
                    self.insert(b"{");
                    self.put_to(Color::Var, e);
                    self.insert(b"}");
                } else {
                    self.put_to(Color::Var, e);
                }
                Act::Stay
            }
            _ => {
                self.put_to(Color::Var, e);
                Act::Stay
            }
        }
    }

    fn dollar_brace(&mut self, ctx: DollarCtx, p: usize) -> Act {
        let inp = self.inp;
        let end = match Self::brace_extent(inp, p + 1) {
            Some(e) => e,
            None => {
                if ctx == DollarCtx::Quote {
                    return self.open_inserted();
                }
                let len = inp.len();
                self.put_to(Color::Var, len);
                return Act::Push(State::Unterminated);
            }
        };
        let content = &inp[p + 2..end - 1];
        let unquotable = content.first().map_or(false, |&c| c == b'#' || c == b'!')
            || content == b"$"
            || content == b"?";
        let pure_ident = !content.is_empty()
            && is_ident_start(content[0])
            && content.iter().all(|&c| is_ident(c));
        match ctx {
            DollarCtx::Quote => {
                if unquotable {
                    self.put_to(Color::Var, end);
                    Act::Stay
                } else {
                    self.open_inserted()
                }
            }
            DollarCtx::Inserted => {
                // ${name[*]} -> ${name[@]}
                let mut ne = 0;
                while ne < content.len() && is_ident(content[ne]) {
                    ne += 1;
                }
                if ne > 0
                    && is_ident_start(content[0])
                    && content.len() >= ne + 3
                    && &content[ne..ne + 3] == b"[*]"
                {
                    let star = p + 2 + ne + 1;
                    self.put_to(Color::Var, star);
                    self.delete_n(Color::Var, 1);
                    self.insert(b"@");
                    self.put_to(Color::Var, end);
                    return Act::Stay;
                }
                if pure_ident {
                    let keep = match inp.get(end) {
                        None => true,
                        Some(&c) if is_ident(c) => true,
                        Some(b'"') => inp.get(end + 1).map_or(false, |&d| is_ident(d)),
                        _ => false,
                    };
                    if !keep {
                        self.put_n(Color::Var, 1);
                        self.delete_n(Color::Var, 1);
                        self.put_to(Color::Var, end - 1);
                        self.delete_n(Color::Var, 1);
                        return Act::Stay;
                    }
                }
                self.put_to(Color::Var, end);
                Act::Stay
            }
            DollarCtx::Dq { at_start } => {
                if at_start
                    && pure_ident
                    && inp.get(end) == Some(&b'"')
                    && inp.get(end + 1).map_or(false, |&d| !is_ident(d))
                {
                    self.put_n(Color::Var, 1);
                    self.delete_n(Color::Var, 1);
                    self.put_to(Color::Var, end - 1);
                    self.delete_n(Color::Var, 1);
                } else {
                    self.put_to(Color::Var, end);
                }
                Act::Stay
            }
            DollarCtx::Plain => {
                self.put_to(Color::Var, end);
                Act::Stay
            }
        }
    }

    // ---------------------------------------------------------------
    // State steps
    // ---------------------------------------------------------------

    fn step(&mut self, st: &mut State) -> Act {
        let c = self.cur();
        match st {
            State::Normal { end, arm } => {
                let (end, arm) = (*end, *arm);
                if arm && c == b';' && self.at(self.pos + 1) == Some(b';') {
                    self.put_n(Color::None, 2);
                    return Act::Pop;
                }
                if self.is_end(end) {
                    self.handle_end(end);
                    return Act::Pop;
                }
                match c {
                    b'#' => {
                        self.comment();
                        Act::Stay
                    }
                    b'(' => {
                        if self.at(self.pos + 1) == Some(b'(') {
                            self.put_n(Color::Magenta, 2);
                            Act::Push(State::Arith { depth: 2 })
                        } else {
                            self.put_n(Color::None, 1);
                            Act::Push(State::Normal { end: End::Paren, arm: false })
                        }
                    }
                    b'\\' => self.escape(),
                    _ if c <= 0x20 || matches!(c, b';' | b'&' | b'|' | b'<' | b'>') => {
                        self.put_n(Color::None, 1);
                        Act::Stay
                    }
                    _ => Act::Replace(State::Command { end, arm, started: false }),
                }
            }
            State::Command { end, arm, started } => {
                let (end, arm) = (*end, *arm);
                if !*started {
                    *started = true;
                    if let Some(act) = self.command_start(end, arm) {
                        return act;
                    }
                }
                if self.is_end(end) {
                    self.handle_end(end);
                    return Act::Pop;
                }
                match c {
                    _ if c <= 0x20 => Act::Replace(State::Args { end, arm }),
                    b';' | b'&' | b'|' | b'(' => Act::Replace(State::Normal { end, arm }),
                    b'"' => self.start_dq(),
                    b'\'' => self.start_sq(),
                    b'\\' => self.escape(),
                    b'$' => self.dollar(DollarCtx::Quote, Color::Cmd),
                    b'`' => self.open_inserted(),
                    _ => {
                        self.put_n(Color::Cmd, 1);
                        Act::Stay
                    }
                }
            }
            State::Args { end, arm } => {
                let (end, arm) = (*end, *arm);
                if self.is_end(end) {
                    self.handle_end(end);
                    return Act::Pop;
                }
                match c {
                    b'\n' | b';' | b'&' | b'|' => Act::Replace(State::Normal { end, arm }),
                    b'#' => {
                        self.comment();
                        Act::Stay
                    }
                    b'"' => self.start_dq(),
                    b'\'' => self.start_sq(),
                    b'\\' => self.escape(),
                    b'$' => self.dollar(DollarCtx::Quote, Color::None),
                    b'`' => self.open_inserted(),
                    b'<' if self.at(self.pos + 1) == Some(b'<') => self.heredoc(Color::None),
                    _ => {
                        self.put_n(Color::None, 1);
                        Act::Stay
                    }
                }
            }
            State::Rvalue { end, arm } => {
                let (end, arm) = (*end, *arm);
                if self.is_end(end) {
                    self.handle_end(end);
                    return Act::Pop;
                }
                match c {
                    _ if c <= 0x20 || matches!(c, b';' | b'&' | b'|') => {
                        Act::Replace(State::Normal { end, arm })
                    }
                    b'(' => {
                        self.put_n(Color::None, 1);
                        Act::Push(State::Array)
                    }
                    b'"' => self.start_dq(),
                    b'\'' => self.start_sq(),
                    b'\\' => self.escape(),
                    b'$' => self.dollar(DollarCtx::Plain, Color::None),
                    b'`' => self.plain_backtick(),
                    b'<' if self.at(self.pos + 1) == Some(b'<') => self.heredoc(Color::None),
                    _ => {
                        self.put_n(Color::None, 1);
                        Act::Stay
                    }
                }
            }
            State::Array => match c {
                b')' => Act::Pop,
                b'#' => {
                    self.comment();
                    Act::Stay
                }
                b'"' => self.start_dq(),
                b'\'' => self.start_sq(),
                b'\\' => self.escape(),
                b'$' => self.dollar(DollarCtx::Quote, Color::None),
                b'`' => self.open_inserted(),
                b'<' if self.at(self.pos + 1) == Some(b'<') => self.heredoc(Color::None),
                _ => {
                    self.put_n(Color::None, 1);
                    Act::Stay
                }
            },
            State::Dq { at_start } => {
                let was_start = *at_start;
                *at_start = false;
                match c {
                    b'"' => {
                        self.put_n(Color::Dq, 1);
                        Act::Pop
                    }
                    b'\\' => self.escape(),
                    b'$' => self.dollar(DollarCtx::Dq { at_start: was_start }, Color::Dq),
                    b'`' => self.dq_backtick(),
                    _ => {
                        self.put_n(Color::Dq, 1);
                        Act::Stay
                    }
                }
            }
            State::Inserted => match c {
                b'$' => self.dollar(DollarCtx::Inserted, Color::Dq),
                b'`' => self.dq_backtick(),
                b'"' => {
                    self.delete_n(Color::Dq, 1);
                    Act::Replace(State::Dq { at_start: true })
                }
                _ => {
                    let inp = self.inp;
                    let mut j = self.pos;
                    while j < inp.len() && is_absorbable(inp[j]) {
                        j += 1;
                    }
                    if j < inp.len() && matches!(inp[j], b'$' | b'"' | b'`') && j > self.pos {
                        self.put_to(Color::Dq, j);
                        Act::Stay
                    } else {
                        self.close_inserted()
                    }
                }
            },
            State::Sq => {
                if c == b'\'' {
                    self.put_n(Color::Sq, 1);
                    Act::Pop
                } else {
                    self.put_n(Color::Sq, 1);
                    Act::Stay
                }
            }
            State::AnsiC => match c {
                b'\'' => {
                    self.put_n(Color::AnsiC, 1);
                    Act::Pop
                }
                b'\\' => self.escape(),
                _ => {
                    self.put_n(Color::AnsiC, 1);
                    Act::Stay
                }
            },
            State::Test { brackets } => match c {
                b']' => {
                    *brackets += 1;
                    self.put_n(Color::Magenta, 1);
                    if *brackets >= 2 {
                        Act::Pop
                    } else {
                        Act::Stay
                    }
                }
                b'"' => self.start_dq(),
                b'\'' => self.start_sq(),
                b'\\' => self.escape(),
                b'$' => self.dollar(DollarCtx::Plain, Color::Magenta),
                b'`' => self.plain_backtick(),
                b'<' if self.at(self.pos + 1) == Some(b'<') => self.heredoc(Color::Magenta),
                _ => {
                    self.put_n(Color::Magenta, 1);
                    Act::Stay
                }
            },
            State::Arith { depth } => match c {
                b'(' => {
                    *depth += 1;
                    self.put_n(Color::Magenta, 1);
                    Act::Stay
                }
                b')' => {
                    *depth -= 1;
                    self.put_n(Color::Magenta, 1);
                    if *depth == 0 {
                        Act::Pop
                    } else {
                        Act::Stay
                    }
                }
                b'"' => self.start_dq(),
                b'\'' => self.start_sq(),
                b'\\' => self.escape(),
                b'$' => self.dollar(DollarCtx::Plain, Color::Magenta),
                b'`' => self.plain_backtick(),
                b'<' if self.at(self.pos + 1) == Some(b'<') => self.heredoc(Color::Magenta),
                _ => {
                    self.put_n(Color::Magenta, 1);
                    Act::Stay
                }
            },
            State::CaseHead { after_ws } => {
                let ws = *after_ws;
                *after_ws = false;
                match c {
                    b'#' => {
                        self.comment();
                        Act::Stay
                    }
                    b'i' if ws
                        && self.at(self.pos + 1) == Some(b'n')
                        && !self.at(self.pos + 2).map_or(false, is_ident) =>
                    {
                        self.put_n(Color::Bold, 2);
                        Act::Replace(State::CaseBody)
                    }
                    b'"' => self.start_dq(),
                    b'\'' => self.start_sq(),
                    b'\\' => self.escape(),
                    b'$' => self.dollar(DollarCtx::Plain, Color::Bold),
                    b'`' => self.plain_backtick(),
                    b' ' | b'\t' | b'\n' => {
                        *after_ws = true;
                        self.put_n(Color::Bold, 1);
                        Act::Stay
                    }
                    _ => {
                        self.put_n(Color::Bold, 1);
                        Act::Stay
                    }
                }
            }
            State::CaseBody => {
                if c == b'e'
                    && self.inp[self.pos..].starts_with(b"esac")
                    && !self.at(self.pos + 4).map_or(false, is_ident)
                    && (self.pos == 0 || !is_ident(self.inp[self.pos - 1]))
                {
                    self.put_n(Color::Bold, 4);
                    return Act::Pop;
                }
                match c {
                    b')' => {
                        self.put_n(Color::None, 1);
                        Act::Push(State::Normal { end: End::None, arm: true })
                    }
                    b'#' => {
                        self.comment();
                        Act::Stay
                    }
                    b'"' => self.start_dq(),
                    b'\'' => self.start_sq(),
                    b'\\' => self.escape(),
                    b'$' => self.dollar(DollarCtx::Plain, Color::None),
                    b'`' => self.plain_backtick(),
                    b'<' if self.at(self.pos + 1) == Some(b'<') => self.heredoc(Color::None),
                    _ => {
                        self.put_n(Color::None, 1);
                        Act::Stay
                    }
                }
            }
            State::ForVar { end, arm } => {
                let (end, arm) = (*end, *arm);
                match c {
                    b' ' | b'\t' => {
                        self.put_n(Color::Bold, 1);
                        Act::Stay
                    }
                    b'\n' | b';' | b'&' | b'|' | b')' => Act::Pop,
                    b'#' => {
                        self.comment();
                        Act::Stay
                    }
                    b'(' if self.at(self.pos + 1) == Some(b'(') => {
                        self.put_n(Color::Magenta, 2);
                        Act::Push(State::Arith { depth: 2 })
                    }
                    b'i' if self.at(self.pos + 1) == Some(b'n')
                        && !self.at(self.pos + 2).map_or(false, is_ident) =>
                    {
                        self.put_n(Color::None, 2);
                        Act::Push(State::ForIn { first: true })
                    }
                    _ => {
                        let inp = self.inp;
                        let mut i = self.pos;
                        while i < inp.len() && is_ident(inp[i]) {
                            i += 1;
                        }
                        let term = match inp.get(i) {
                            None => true,
                            Some(&t) => t <= 0x20 || matches!(t, b';' | b'&' | b'|' | b')' | b'#'),
                        };
                        if i > self.pos && term {
                            self.put_to(Color::Assign, i);
                            Act::Stay
                        } else {
                            self.put_to(Color::Assign, i);
                            Act::Replace(State::Command { end, arm, started: true })
                        }
                    }
                }
            }
            State::ForIn { first } => {
                match c {
                    b'\n' | b';' | b'&' | b'|' => return Act::Pop,
                    b'#' => {
                        self.comment();
                        return Act::Stay;
                    }
                    _ if c <= 0x20 => {
                        self.put_n(Color::None, 1);
                        return Act::Stay;
                    }
                    _ => {}
                }
                let was_first = *first;
                *first = false;
                match c {
                    b'$' => {
                        if was_first {
                            let inp = self.inp;
                            if let Some(&n) = inp.get(self.pos + 1) {
                                if is_ident_start(n) {
                                    let mut e = self.pos + 1;
                                    while e < inp.len() && is_ident(inp[e]) {
                                        e += 1;
                                    }
                                    let mut k = e;
                                    while k < inp.len() && inp[k] == b' ' {
                                        k += 1;
                                    }
                                    if matches!(inp.get(k), Some(b';') | Some(b'\n')) {
                                        self.insert(b"\"");
                                        self.put_n(Color::Var, 1);
                                        self.insert(b"{");
                                        self.put_to(Color::Var, e);
                                        self.insert(b"[@]}\"");
                                        return Act::Pop;
                                    }
                                }
                            }
                        }
                        self.dollar(DollarCtx::Quote, Color::None)
                    }
                    b'"' => self.start_dq(),
                    b'\'' => self.start_sq(),
                    b'\\' => self.escape(),
                    b'`' => self.open_inserted(),
                    b'<' if self.at(self.pos + 1) == Some(b'<') => self.heredoc(Color::None),
                    _ => {
                        self.put_n(Color::None, 1);
                        Act::Stay
                    }
                }
            }
            State::Heredoc { delim, dash } => {
                let delim = std::mem::take(delim);
                let dash = *dash;
                let act = self.step_heredoc(&delim, dash);
                if let State::Heredoc { delim: d, .. } = st {
                    *d = delim;
                }
                act
            }
            State::Unterminated => {
                // Should not be stepped; consume to end.
                let len = self.inp.len();
                self.put_to(Color::None, len);
                Act::Stay
            }
        }
    }

    /// Checks done at the start of a command word: assignments and keywords.
    fn command_start(&mut self, end: End, arm: bool) -> Option<Act> {
        let inp = self.inp;
        let p = self.pos;
        let c = inp[p];
        // Assignment?
        if is_ident_start(c) {
            let mut i = p;
            while i < inp.len() && is_ident(inp[i]) {
                i += 1;
            }
            let mut ok = true;
            while ok && inp.get(i) == Some(&b'[') {
                let mut j = i + 1;
                loop {
                    match inp.get(j) {
                        None | Some(b'\\') => {
                            ok = false;
                            break;
                        }
                        Some(b']') => {
                            i = j + 1;
                            break;
                        }
                        _ => j += 1,
                    }
                }
            }
            if ok {
                if inp.get(i) == Some(&b'=') {
                    self.put_to(Color::Assign, i);
                    self.put_n(Color::None, 1);
                    return Some(Act::Replace(State::Rvalue { end, arm }));
                }
                if inp.get(i) == Some(&b'+') && inp.get(i + 1) == Some(&b'=') {
                    self.put_to(Color::Assign, i);
                    self.put_n(Color::None, 2);
                    return Some(Act::Replace(State::Rvalue { end, arm }));
                }
            }
        }
        // Keyword?
        let mut j = p;
        while j < inp.len() {
            let d = inp[j];
            if is_kw_term(d) || matches!(d, b'"' | b'\'' | b'$' | b'`' | b'\\' | b'=') {
                break;
            }
            j += 1;
        }
        let word = &inp[p..j];
        let term_ok = j == inp.len() || is_kw_term(inp[j]);
        if !term_ok {
            return None;
        }
        match word {
            b"if" | b"then" | b"elif" | b"else" | b"fi" | b"do" | b"done" | b"while" | b"until"
            | b"function" | b"declare" | b"local" | b"export" | b"readonly" | b"{" | b"}"
            | b"!" => {
                self.put_to(Color::Bold, j);
                Some(Act::Replace(State::Normal { end, arm }))
            }
            b"for" | b"select" => {
                self.put_to(Color::Bold, j);
                match inp.get(j) {
                    None => Some(Act::ReplacePush(
                        State::Normal { end, arm },
                        State::ForVar { end, arm },
                    )),
                    Some(b' ') | Some(b'\t') => {
                        let mut k = j;
                        while matches!(inp.get(k), Some(b' ') | Some(b'\t')) {
                            k += 1;
                        }
                        self.put_to(Color::Bold, k);
                        Some(Act::ReplacePush(
                            State::Normal { end, arm },
                            State::ForVar { end, arm },
                        ))
                    }
                    _ => Some(Act::Replace(State::Normal { end, arm })),
                }
            }
            b"case" => {
                self.put_to(Color::Bold, j);
                Some(Act::ReplacePush(
                    State::Normal { end, arm },
                    State::CaseHead { after_ws: true },
                ))
            }
            b"[[" => {
                if j == inp.len() || inp[j] <= 0x20 {
                    self.put_to(Color::Magenta, j);
                    Some(Act::ReplacePush(
                        State::Normal { end, arm },
                        State::Test { brackets: 0 },
                    ))
                } else {
                    None
                }
            }
            b"esac" if arm => {
                self.insert(b";; ");
                Some(Act::Pop)
            }
            b"[" | b"test" => {
                if inp.get(j) == Some(&b' ') && inp.get(j + 1) != Some(&b' ') {
                    self.put_to(Color::Cmd, j + 1);
                } else {
                    self.put_to(Color::Cmd, j);
                }
                Some(Act::Replace(State::Args { end, arm }))
            }
            _ => None,
        }
    }
}

/// Whether a state may silently end at end of file.
fn eof_ok(st: &State) -> bool {
    match st {
        State::Normal { end: End::None, .. }
        | State::Command { end: End::None, .. }
        | State::Args { end: End::None, .. }
        | State::Rvalue { end: End::None, .. } => true,
        _ => false,
    }
}

fn run(inp: &[u8], out: Out) -> (Out, Result<(), ParseError>) {
    let mut m = Machine { inp, pos: 0, out };
    let mut stack: Vec<State> = vec![State::Normal { end: End::None, arm: false }];
    loop {
        if m.pos >= inp.len() {
            // End of file: unwind what can be unwound.
            loop {
                if stack.len() <= 1 {
                    return (m.out, Ok(()));
                }
                let top = stack.last().unwrap();
                match top {
                    State::Inserted => {
                        m.insert(b"\"");
                        stack.pop();
                    }
                    s if eof_ok(s) => {
                        stack.pop();
                    }
                    _ => return (m.out, Err(ParseError::Eof)),
                }
            }
        }
        let act = {
            let top = stack.last_mut().unwrap();
            m.step(top)
        };
        match act {
            Act::Stay => {}
            Act::Push(s) => stack.push(s),
            Act::Pop => {
                stack.pop();
                if stack.is_empty() {
                    // Should not happen; keep a base state.
                    stack.push(State::Normal { end: End::None, arm: false });
                }
            }
            Act::Replace(s) => {
                stack.pop();
                stack.push(s);
            }
            Act::ReplacePush(a, b) => {
                stack.pop();
                stack.push(a);
                stack.push(b);
            }
            Act::Err(e) => return (m.out, Err(e)),
        }
    }
}

