const HELP: &str = "Shellharden: The corrective bash syntax highlighter.

Usage:
\tshellharden [options] [files]
\tcat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
\t--suggest         Output a colored diff suggesting changes.
\t--syntax          Output syntax highlighting with ANSI colors.
\t--syntax-suggest  Diff with syntax highlighting (default mode).
\t--transform       Output suggested changes.
\t--check           No output; exit with 2 if changes are suggested.
\t--replace         Replace file contents with suggested changes.
\t--                Don't treat further arguments as options.
\t-h|--help         Show help text.
\t--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md

";

const VERSION: &str = "4.3.1";

const PITFALL_TEXT: &str = "This does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.

Try this and be shocked: f() { echo \"$9\" \"$10\"; }; f a b c d e f g h i j

Here is where braces should be used to disambiguate, e.g. \"${10}\" vs \"${1}0\".

Syntactic pitfalls are deemed too dangerous to fix automatically
(the purpose of Shellharden is to fix vulnerable code \u{2013} code that mostly does what it looks like, as opposed to code that never does what it looks like):
* Fixing what it does would be 100% subtle and might slip through code review unnoticed.
* Fixing its look would make a likely bug look intentional.
";

const EOF_TEXT: &str = "The file's end was reached without closing all sytactic scopes.
Either, the parser got lost, or the file is truncated or malformed.
";

#[derive(Clone, Copy, PartialEq, Eq)]
enum Mode {
    Suggest,
    Syntax,
    SyntaxSuggest,
    Transform,
    Check,
    Replace,
}

fn make_out(mode: Mode) -> Out {
    match mode {
        Mode::Suggest => Out::new(false, true, false),
        Mode::Syntax => Out::new(true, false, false),
        Mode::SyntaxSuggest => Out::new(true, true, false),
        Mode::Transform | Mode::Check | Mode::Replace => Out::new(false, false, true),
    }
}

fn write_stderr(bytes: &[u8]) {
    let stderr = io::stderr();
    let mut h = stderr.lock();
    let _ = h.write_all(bytes);
    let _ = h.flush();
}

fn write_stdout(bytes: &[u8]) {
    let stdout = io::stdout();
    let mut h = stdout.lock();
    let _ = h.write_all(bytes);
    let _ = h.flush();
}

const HORIZON: usize = 128;

fn format_parse_error(name: &str, inp: &[u8], e: &ParseError) -> Vec<u8> {
    let mut msg = Vec::new();
    match e {
        ParseError::Eof => {
            msg.extend_from_slice(name.as_bytes());
            msg.extend_from_slice(b": Unexpected end of file\n");
            msg.extend_from_slice(EOF_TEXT.as_bytes());
        }
        ParseError::Pitfall { start, end } => {
            msg.extend_from_slice(name.as_bytes());
            msg.extend_from_slice(b": Unsupported syntax: Syntactic pitfall\n");
            // Approximate the view window of the original's input buffer.
            let win_start = start - start % HORIZON;
            let win_end = (win_start + HORIZON).min(inp.len());
            let mut ls = *start;
            while ls > win_start && inp[ls - 1] != b'\n' {
                ls -= 1;
            }
            let mut le = *end;
            while le < win_end && inp[le] != b'\n' {
                le += 1;
            }
            msg.extend_from_slice(&inp[ls..le]);
            msg.push(b'\n');
            for _ in ls..*start {
                msg.push(b' ');
            }
            for _ in *start..*end {
                msg.push(b'^');
            }
            msg.push(b'\n');
            msg.extend_from_slice(PITFALL_TEXT.as_bytes());
        }
    }
    msg
}

struct Status {
    error: bool,
}

fn read_all<R: Read>(mut r: R) -> io::Result<Vec<u8>> {
    let mut v = Vec::new();
    r.read_to_end(&mut v)?;
    Ok(v)
}

fn process(name: &str, mode: Mode, status: &mut Status) {
    let is_stdin = name.is_empty();
    // Acquire input.
    let data: Vec<u8> = if is_stdin {
        match read_all(io::stdin().lock()) {
            Ok(d) => d,
            Err(e) => {
                report_io(name, mode, &e, true);
                status.error = true;
                return;
            }
        }
    } else if mode == Mode::Replace {
        let mut f = match File::open(name) {
            Ok(f) => f,
            Err(e) => {
                report_io(name, mode, &e, false);
                status.error = true;
                return;
            }
        };
        if let Err(e) = f.seek(SeekFrom::End(0)) {
            report_io(name, mode, &e, false);
            status.error = true;
            return;
        }
        if let Err(e) = f.seek(SeekFrom::Start(0)) {
            report_io(name, mode, &e, false);
            status.error = true;
            return;
        }
        match read_all(&f) {
            Ok(d) => d,
            Err(e) => {
                report_io(name, mode, &e, false);
                status.error = true;
                return;
            }
        }
    } else {
        let f = match File::open(name) {
            Ok(f) => f,
            Err(e) => {
                report_io(name, mode, &e, false);
                status.error = true;
                return;
            }
        };
        match read_all(&f) {
            Ok(d) => d,
            Err(e) => {
                report_io(name, mode, &e, true);
                status.error = true;
                return;
            }
        }
    };

    let (mut out, res) = run(&data, make_out(mode));
    out.finish();

    match mode {
        Mode::Check => {
            if res.is_err() || out.changed {
                std::process::exit(2);
            }
        }
        Mode::Replace if !is_stdin => {
            if let Err(e) = res {
                write_stderr(&format_parse_error(name, &data, &e));
                status.error = true;
                return;
            }
            if out.changed {
                let r = File::options()
                    .write(true)
                    .truncate(true)
                    .open(name)
                    .and_then(|mut f| f.write_all(&out.buf));
                if let Err(e) = r {
                    report_io(name, mode, &e, false);
                    status.error = true;
                }
            }
        }
        _ => {
            if let Err(e) = res {
                out.buf.push(b'\n');
                write_stdout(&out.buf);
                write_stderr(&format_parse_error(name, &data, &e));
                status.error = true;
            } else {
                write_stdout(&out.buf);
            }
        }
    }
}

fn report_io(name: &str, mode: Mode, e: &io::Error, newline_on_stdout: bool) {
    if newline_on_stdout && !matches!(mode, Mode::Check | Mode::Replace) {
        write_stdout(b"\n");
    }
    let msg = format!("{}: {}\n", name, e);
    write_stderr(msg.as_bytes());
}

fn main() {
    let args: Vec<std::ffi::OsString> = std::env::args_os().skip(1).collect();
    let mut mode = Mode::SyntaxSuggest;
    let mut status = Status { error: false };
    let mut opts_done = false;
    for arg in args {
        let s = arg.to_string_lossy().into_owned();
        if !opts_done && s.starts_with('-') {
            match s.as_str() {
                "--" => opts_done = true,
                "--suggest" => mode = Mode::Suggest,
                "--syntax" => mode = Mode::Syntax,
                "--syntax-suggest" => mode = Mode::SyntaxSuggest,
                "--transform" => mode = Mode::Transform,
                "--check" => mode = Mode::Check,
                "--replace" => mode = Mode::Replace,
                "-h" | "--help" => write_stdout(HELP.as_bytes()),
                "--version" => {
                    let mut v = VERSION.to_string();
                    v.push('\n');
                    write_stdout(v.as_bytes());
                }
                _ => {
                    let msg = format!("{}: No such option.\n", s);
                    write_stderr(msg.as_bytes());
                    std::process::exit(3);
                }
            }
            continue;
        }
        process(&s, mode, &mut status);
    }
    if status.error {
        std::process::exit(1);
    }
}
