// ---------------------------------------------------------------------------
// Parser states
// ---------------------------------------------------------------------------

/// Size of the input window the original tool works with. Some lookahead
/// decisions are limited by it.
const HORIZON: usize = 128;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum End {
    None,
    Paren,
    Backtick { convert: bool },
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum DollarCtx {
    /// Unquoted word context: expansions get quoted.
    Quote(End),
    /// Inside a double quote inserted by us.
    Inserted,
    /// Inside a user's double quoted string.
    Dq { at_start: bool },
    /// Context where no quoting is needed (rvalue, test, arith, case ...).
    Plain,
}

#[derive(Debug)]
enum State {
    Normal { end: End, arm: bool },
    Command { end: End, arm: bool, started: bool },
    /// Right after `[ ` or `test `: looks for rewritable patterns.
    TestCmd { end: End, arm: bool },
    Args { end: End, arm: bool },
    Rvalue { end: End, arm: bool },
    Array,
    Dq { at_start: bool },
    Inserted { end: End },
    Sq,
    AnsiC,
    /// `[[ ]]`, `(( ))` and `$(( ))`: a stack of expected closing brackets.
    Brackets { stack: Vec<u8> },
    CaseHead { after_ws: bool },
    CaseBody,
    ForVar { end: End, arm: bool },
    ForIn { first: bool },
    Heredoc { delim: Vec<u8>, dash: bool },
    /// Argument of `[ -n` / `[ -z`: rewritten to a comparison with "".
    TestArg { suffix: &'static [u8], done: bool, end: End },
    /// `[ x"$a" = xb ]`: removes the x prefixes. `rx` is the second x.
    XHack { rx: usize, end: End, arm: bool },
    /// Something that was opened but can never be closed (EOF reached).
    Unterminated,
}

enum Act {
    Stay,
    Push(State),
    Pop,
    Replace(State),
    ReplacePush(State, State),
    Err(ParseError),
}

#[derive(Debug)]
enum ParseError {
    Eof,
    Pitfall { start: usize, end: usize },
}

fn is_ident_start(c: u8) -> bool {
    c == b'_' || c.is_ascii_alphabetic()
}

fn is_ident(c: u8) -> bool {
    c == b'_' || c.is_ascii_alphanumeric()
}

fn is_absorbable(c: u8) -> bool {
    match c {
        b'+' | b',' | b'-' | b'.' | b'/' | b':' | b'=' | b'@' | b'[' | b']' | b'^' | b'_' | b'{'
        | b'}' | b'~' => true,
        _ => c.is_ascii_alphanumeric() || c >= 127,
    }
}

fn is_kw_term(c: u8) -> bool {
    c <= 0x20 || matches!(c, b';' | b'&' | b'|' | b'(' | b')' | b'<' | b'>')
}

struct Machine<'a> {
    inp: &'a [u8],
    pos: usize,
    out: Out,
    /// Start of the emulated input window.
    ws: usize,
    /// Position where the current step started.
    step_start: usize,
}

impl<'a> Machine<'a> {
    fn at(&self, i: usize) -> Option<u8> {
        self.inp.get(i).copied()
    }

    fn cur(&self) -> u8 {
        self.inp[self.pos]
    }

    /// End of the window visible to the current step.
    fn we(&self) -> usize {
        let k = (self.step_start - self.ws) / HORIZON;
        (self.ws + HORIZON * (k + 1)).min(self.inp.len())
    }

    /// Look at a byte; if it lies beyond the visible window, the original
    /// tool would have asked for more input, which moves the window start to
    /// the position where the current step began.
    fn peek(&mut self, i: usize) -> Option<u8> {
        if i < self.inp.len() && i >= self.we() {
            self.ws = self.step_start;
        }
        self.inp.get(i).copied()
    }

    /// Mark that a scan looked at everything up to and including index `i`.
    fn touch(&mut self, i: usize) {
        let i = i.min(self.inp.len() - 1);
        self.peek(i);
    }

    /// Mark that a scan ran into the end of input.
    fn touch_eof(&mut self) {
        if self.we() < self.inp.len() {
            self.ws = self.step_start;
        }
    }

    /// Byte at `i` only if it is inside the visible window (decisions made
    /// without asking for more input).
    fn vis(&self, i: usize) -> Option<u8> {
        if i >= self.we() {
            None
        } else {
            self.inp.get(i).copied()
        }
    }

    fn put_n(&mut self, c: Color, n: usize) {
        let end = (self.pos + n).min(self.inp.len());
        let bytes = &self.inp[self.pos..end];
        self.out.put(c, bytes);
        self.pos = end;
    }

    fn put_to(&mut self, c: Color, end: usize) {
        let bytes = &self.inp[self.pos..end];
        self.out.put(c, bytes);
        self.pos = end;
    }

    fn delete_n(&mut self, c: Color, n: usize) {
        let end = (self.pos + n).min(self.inp.len());
        let bytes = &self.inp[self.pos..end];
        self.out.delete(c, bytes);
        self.pos = end;
    }

    fn insert(&mut self, bytes: &[u8]) {
        self.out.insert(bytes);
    }

    fn is_end(&self, end: End) -> bool {
        match end {
            End::None => false,
            End::Paren => self.cur() == b')',
            End::Backtick { .. } => self.cur() == b'`',
        }
    }

    /// Consume the end trigger of a command list context.
    fn handle_end(&mut self, end: End) {
        match end {
            End::None => {}
            End::Paren => self.put_n(Color::None, 1),
            End::Backtick { convert } => {
                if convert {
                    self.delete_n(Color::None, 1);
                    self.insert(b")");
                } else {
                    self.put_n(Color::None, 1);
                }
            }
        }
    }

    fn escape(&mut self) -> Act {
        if self.pos + 1 < self.inp.len() {
            self.put_n(Color::Esc, 2);
            Act::Stay
        } else {
            self.put_n(Color::Esc, 1);
            Act::Push(State::Unterminated)
        }
    }

    fn comment(&mut self) {
        let mut j = self.pos;
        while j < self.inp.len() && self.inp[j] != b'\n' {
            j += 1;
        }
        self.put_to(Color::Comment, j);
    }

    fn start_dq(&mut self) -> Act {
        self.put_n(Color::Dq, 1);
        Act::Push(State::Dq { at_start: true })
    }

    fn start_sq(&mut self) -> Act {
        self.put_n(Color::Sq, 1);
        Act::Push(State::Sq)
    }

    // ---------------------------------------------------------------
    // Scanning helpers (all record how far they looked)
    // ---------------------------------------------------------------

    /// End of the identifier starting at `i` (exclusive), looking past it.
    fn ident_end(&mut self, i: usize) -> usize {
        let mut e = i;
        while e < self.inp.len() && is_ident(self.inp[e]) {
            e += 1;
        }
        self.touch(e);
        e
    }

    /// Index just past the `}` closing the `${` whose `{` is at `brace`.
    fn brace_extent(&mut self, brace: usize) -> Option<usize> {
        let inp = self.inp;
        let mut i = brace + 1;
        loop {
            match inp.get(i) {
                None => {
                    self.touch_eof();
                    return None;
                }
                Some(b'\\') => i += 2,
                Some(b'$') if inp.get(i + 1) == Some(&b'{') => {
                    i = self.brace_extent(i + 1)?;
                }
                Some(b'}') => {
                    self.touch(i);
                    return Some(i + 1);
                }
                Some(_) => i += 1,
            }
        }
    }

    /// Index just past the backtick closing the one at `p`.
    fn closing_backtick(&mut self, p: usize) -> Option<usize> {
        let inp = self.inp;
        let mut i = p + 1;
        loop {
            match inp.get(i) {
                None => {
                    self.touch_eof();
                    return None;
                }
                Some(b'\\') => i += 2,
                Some(b'`') => {
                    self.touch(i);
                    return Some(i + 1);
                }
                Some(_) => i += 1,
            }
        }
    }

    /// Index just past the parenthesis closing the one at `p`.
    fn closing_paren(&mut self, p: usize) -> Option<usize> {
        let inp = self.inp;
        let mut i = p + 1;
        let mut depth = 1;
        loop {
            match inp.get(i) {
                None => {
                    self.touch_eof();
                    return None;
                }
                Some(b'\\') => i += 2,
                Some(b'(') => {
                    depth += 1;
                    i += 1;
                }
                Some(b')') => {
                    depth -= 1;
                    if depth == 0 {
                        self.touch(i);
                        return Some(i + 1);
                    }
                    i += 1;
                }
                Some(_) => i += 1,
            }
        }
    }

    fn closing_dq(&mut self, u: usize) -> Option<usize> {
        let inp = self.inp;
        let mut i = u + 1;
        loop {
            match inp.get(i) {
                None => {
                    self.touch_eof();
                    return None;
                }
                Some(b'\\') => i += 2,
                Some(b'"') => {
                    self.touch(i);
                    return Some(i + 1);
                }
                Some(_) => i += 1,
            }
        }
    }

    fn closing_sq(&mut self, u: usize) -> Option<usize> {
        let inp = self.inp;
        let mut i = u + 1;
        while i < inp.len() && inp[i] != b'\'' {
            i += 1;
        }
        if i < inp.len() {
            self.touch(i);
            Some(i + 1)
        } else {
            self.touch_eof();
            None
        }
    }

    /// After an expansion ending at `e`, can the quoting decision be made?
    fn need_after(&mut self, e: usize) -> bool {
        match self.peek(e) {
            None => false,
            Some(b'"') => self.peek(e + 1).is_some(),
            Some(_) => true,
        }
    }

    fn is_var_start(c: u8) -> bool {
        is_ident_start(c)
            || c.is_ascii_digit()
            || matches!(c, b'{' | b'(' | b'@' | b'*' | b'-' | b'?' | b'$' | b'!' | b'#')
    }

    /// Whether the special character at `j` lets an inserted double quote
    /// absorb the preceding plain characters.
    fn absorb_ok(&mut self, j: usize) -> bool {
        let inp = self.inp;
        match inp[j] {
            b'"' => true,
            b'`' => match self.closing_backtick(j) {
                Some(e) => self.need_after(e),
                None => false,
            },
            b'$' => match self.peek(j + 1) {
                None => false,
                Some(c) if is_ident_start(c) => {
                    let e = self.ident_end(j + 1);
                    self.need_after(e)
                }
                Some(b'{') => match self.brace_extent(j + 1) {
                    None => false,
                    Some(e) => {
                        let content = &inp[j + 2..e - 1];
                        Self::unquotable(content) || self.need_after(e)
                    }
                },
                Some(b'(') => {
                    if self.peek(j + 2) == Some(b'(') {
                        true
                    } else {
                        match self.closing_paren(j + 1) {
                            Some(e) => self.need_after(e),
                            None => false,
                        }
                    }
                }
                Some(c) => {
                    c.is_ascii_digit() || matches!(c, b'@' | b'-' | b'?' | b'$' | b'!' | b'#' | b'*')
                }
            },
            _ => false,
        }
    }

    fn unquotable(content: &[u8]) -> bool {
        content.first().map_or(false, |&c| c == b'#' || c == b'!')
            || content == b"$"
            || content == b"?"
    }

    /// Extent of a `$` expansion starting at `p` (None if not an expansion).
    fn dollar_extent(&mut self, p: usize) -> Option<usize> {
        match self.peek(p + 1)? {
            c if is_ident_start(c) => Some(self.ident_end(p + 1)),
            b'{' => self.brace_extent(p + 1),
            b'(' => {
                self.peek(p + 2);
                self.closing_paren(p + 1)
            }
            b'\'' => {
                let inp = self.inp;
                let mut i = p + 2;
                loop {
                    match inp.get(i) {
                        None => {
                            self.touch_eof();
                            return None;
                        }
                        Some(b'\\') => i += 2,
                        Some(b'\'') => {
                            self.touch(i);
                            return Some(i + 1);
                        }
                        Some(_) => i += 1,
                    }
                }
            }
            c if c.is_ascii_digit() || matches!(c, b'@' | b'*' | b'-' | b'?' | b'$' | b'!' | b'#') => {
                Some(p + 2)
            }
            _ => None,
        }
    }

    /// Extent of a quoted unit starting at `u` (for the x-hack lookahead).
    /// Units whose end cannot be seen within the window make the x-hack give
    /// up (Err) rather than ask for more input.
    fn unit_extent(&mut self, u: usize) -> Option<usize> {
        let inp = self.inp;
        match self.peek(u)? {
            b'"' => self.closing_dq(u),
            b'\'' => self.closing_sq(u),
            b'`' => {
                let mut i = u + 1;
                loop {
                    match self.vis(i) {
                        None => return None,
                        Some(b'\\') => i += 2,
                        Some(b'`') => break,
                        Some(_) => i += 1,
                    }
                }
                let mut e = i + 1;
                loop {
                    match self.peek(e) {
                        Some(b'$') => e = self.dollar_extent(e)?,
                        Some(b'`') => e = self.closing_backtick(e)?,
                        Some(b'"') => e = self.closing_dq(e)?,
                        Some(c) if is_absorbable(c) => {
                            let mut j = e;
                            while j < inp.len() && is_absorbable(inp[j]) {
                                j += 1;
                            }
                            self.touch(j);
                            if j < inp.len() && matches!(inp[j], b'$' | b'"' | b'`') && self.absorb_ok(j) {
                                e = j;
                            } else {
                                break;
                            }
                        }
                        _ => break,
                    }
                }
                Some(e)
            }
            b'$' => {
                let mut e = match self.vis(u + 1)? {
                    c if is_ident_start(c) => self.ident_end(u + 1),
                    b'{' => {
                        // Give up unless the closing brace and the byte after
                        // it are visible.
                        let mut i = u + 2;
                        loop {
                            match self.vis(i) {
                                None => return None,
                                Some(b'\\') => i += 2,
                                Some(b'}') => break,
                                Some(_) => i += 1,
                            }
                        }
                        self.vis(i + 1)?;
                        i + 1
                    }
                    b'(' => {
                        if self.vis(u + 2) == Some(b'(') {
                            self.closing_paren(u + 1)?
                        } else {
                            let mut i = u + 2;
                            let mut depth = 1;
                            loop {
                                match self.vis(i) {
                                    None => return None,
                                    Some(b'\\') => i += 2,
                                    Some(b'(') => {
                                        depth += 1;
                                        i += 1;
                                    }
                                    Some(b')') => {
                                        depth -= 1;
                                        if depth == 0 {
                                            break;
                                        }
                                        i += 1;
                                    }
                                    Some(_) => i += 1,
                                }
                            }
                            self.vis(i + 1)?;
                            i + 1
                        }
                    }
                    b'\'' => self.dollar_extent(u)?,
                    c if c.is_ascii_digit()
                        || matches!(c, b'@' | b'*' | b'-' | b'?' | b'$' | b'!' | b'#') =>
                    {
                        u + 2
                    }
                    _ => return None,
                };
                loop {
                    match self.peek(e) {
                        Some(b'$') => e = self.dollar_extent(e)?,
                        Some(b'`') => e = self.closing_backtick(e)?,
                        Some(b'"') => e = self.closing_dq(e)?,
                        Some(c) if is_absorbable(c) => {
                            let mut j = e;
                            while j < inp.len() && is_absorbable(inp[j]) {
                                j += 1;
                            }
                            self.touch(j);
                            if j < inp.len() && matches!(inp[j], b'$' | b'"' | b'`') && self.absorb_ok(j) {
                                e = j;
                            } else {
                                break;
                            }
                        }
                        _ => break,
                    }
                }
                Some(e)
            }
            _ => None,
        }
    }

    /// Can the argument at `p` be rewritten by the `[ -n` / `[ -z` logic?
    fn test_unit_ok(&mut self, p: usize) -> bool {
        match self.peek(p) {
            Some(b'"') | Some(b'\'') | Some(b'\\') => true,
            Some(b'`') => match self.closing_backtick(p) {
                Some(e) => self.peek(e).is_some(),
                None => false,
            },
            Some(b'$') => match self.peek(p + 1) {
                Some(b'\'') => true,
                Some(b'{') => match self.brace_extent(p + 1) {
                    Some(e) => self.peek(e).is_some(),
                    None => false,
                },
                Some(b'(') => {
                    if self.peek(p + 2) == Some(b'(') {
                        true
                    } else {
                        match self.closing_paren(p + 1) {
                            Some(e) => self.peek(e).is_some(),
                            None => false,
                        }
                    }
                }
                Some(c) => Self::is_var_start(c),
                None => false,
            },
            _ => false,
        }
    }

    // ---------------------------------------------------------------
    // pwd substitution
    // ---------------------------------------------------------------

    /// Whether a `$PWD` substitution ending at `e` needs braces.
    fn pwd_braces(&self, e: usize) -> bool {
        match self.at(e) {
            Some(c) if is_ident(c) => true,
            Some(b'"') => self.at(e + 1).map_or(false, is_ident),
            _ => false,
        }
    }

    /// `pwd` → `$PWD` when the command substitution at pos is exactly `pwd`.
    /// Returns true if the rewrite was done.
    fn try_pwd_backtick(&mut self) -> bool {
        let inp = self.inp;
        let p = self.pos;
        if inp[p..].starts_with(b"`pwd`") && self.need_after(p + 5) {
            self.delete_n(Color::Var, 5);
            if self.pwd_braces(p + 5) {
                self.insert(b"${PWD}");
            } else {
                self.insert(b"$PWD");
            }
            return true;
        }
        false
    }

    fn pwd_paren(&mut self) {
        let p = self.pos;
        self.put_n(Color::Var, 1);
        self.delete_n(Color::Var, 5);
        if self.pwd_braces(p + 6) {
            self.insert(b"{PWD}");
        } else {
            self.insert(b"PWD");
        }
    }

    /// Backtick in a context where no quoting is required.
    fn plain_backtick(&mut self) -> Act {
        // The original looks for the closing backtick (and what follows).
        if let Some(e) = self.closing_backtick(self.pos) {
            self.need_after(e);
        }
        if self.try_pwd_backtick() {
            return Act::Stay;
        }
        self.put_n(Color::None, 1);
        Act::Push(State::Normal { end: End::Backtick { convert: false }, arm: false })
    }

    /// Backtick inside a double quoted string: converted to $( ).
    fn dq_backtick(&mut self) -> Act {
        if let Some(e) = self.closing_backtick(self.pos) {
            self.need_after(e);
        }
        if self.try_pwd_backtick() {
            return Act::Stay;
        }
        self.delete_n(Color::None, 1);
        self.insert(b"$(");
        Act::Push(State::Normal { end: End::Backtick { convert: true }, arm: false })
    }

    /// Start of a quoted expansion in an unquoted context.
    fn open_inserted(&mut self, end: End) -> Act {
        self.insert(b"\"");
        Act::Push(State::Inserted { end })
    }

    fn close_inserted(&mut self) -> Act {
        self.insert(b"\"");
        Act::Pop
    }

    // ---------------------------------------------------------------
    // Heredoc
    // ---------------------------------------------------------------

    /// Called with pos at "<<". `color` is the color of the calling state.
    fn heredoc(&mut self, color: Color) -> Act {
        let inp = self.inp;
        let start = self.pos;
        let mut p = start + 2;
        if self.peek(p) == Some(b'<') {
            self.put_n(color, 3);
            return Act::Stay;
        }
        let mut dash = false;
        if inp.get(p) == Some(&b'-') {
            dash = true;
            p += 1;
        }
        while matches!(inp.get(p), Some(b' ') | Some(b'\t') | Some(b'\n')) {
            p += 1;
        }
        let mut delim: Vec<u8> = Vec::new();
        let mut fallback = false;
        'outer: loop {
            match inp.get(p) {
                None => {
                    fallback = true;
                    break;
                }
                Some(b'\\') => match inp.get(p + 1) {
                    None => {
                        fallback = true;
                        break;
                    }
                    Some(b'\n') => p += 2,
                    Some(&c) => {
                        delim.push(c);
                        p += 2;
                    }
                },
                Some(b'"') => {
                    p += 1;
                    loop {
                        match inp.get(p) {
                            None => {
                                fallback = true;
                                break 'outer;
                            }
                            Some(b'"') => {
                                p += 1;
                                break;
                            }
                            Some(b'\\') => match inp.get(p + 1) {
                                None => {
                                    fallback = true;
                                    break 'outer;
                                }
                                Some(&c) if c == b'"' || c == b'\\' || c == b'$' || c == b'`' => {
                                    delim.push(c);
                                    p += 2;
                                }
                                Some(b'\n') => p += 2,
                                Some(&c) => {
                                    delim.push(b'\\');
                                    delim.push(c);
                                    p += 2;
                                }
                            },
                            Some(&c) => {
                                delim.push(c);
                                p += 1;
                            }
                        }
                    }
                }
                Some(b'\'') => {
                    p += 1;
                    loop {
                        match inp.get(p) {
                            None => {
                                fallback = true;
                                break 'outer;
                            }
                            Some(b'\'') => {
                                p += 1;
                                break;
                            }
                            Some(&c) => {
                                delim.push(c);
                                p += 1;
                            }
                        }
                    }
                }
                Some(b' ') | Some(b'\t') | Some(b'\n') => break,
                Some(&c) => {
                    delim.push(c);
                    p += 1;
                }
            }
        }
        if fallback {
            self.touch_eof();
            self.put_n(color, 2);
            return Act::Stay;
        }
        self.touch(p);
        if delim.is_empty() {
            self.put_to(color, p);
            return Act::Stay;
        }
        // Rest of the line belongs to the heredoc.
        let mut q = p;
        while q < inp.len() && inp[q] != b'\n' {
            q += 1;
        }
        if q < inp.len() {
            q += 1;
            self.touch(q - 1);
        } else {
            self.touch_eof();
        }
        self.put_to(Color::Heredoc, q);
        Act::Push(State::Heredoc { delim, dash })
    }

    fn step_heredoc(&mut self, delim: &[u8], dash: bool) -> Act {
        let inp = self.inp;
        let mut q = self.pos;
        while q < inp.len() && inp[q] != b'\n' {
            q += 1;
        }
        let line = &inp[self.pos..q];
        let stripped: &[u8] = if dash {
            let mut k = 0;
            while k < line.len() && line[k] == b'\t' {
                k += 1;
            }
            &line[k..]
        } else {
            line
        };
        if stripped == delim {
            self.put_to(Color::Heredoc, q);
            return Act::Pop;
        }
        if q < inp.len() {
            q += 1;
        }
        self.put_to(Color::Heredoc, q);
        Act::Stay
    }

    // ---------------------------------------------------------------
    // Dollar expansions
    // ---------------------------------------------------------------

    /// Called with pos at '$'. `color` is the color of the calling state.
    fn dollar(&mut self, ctx: DollarCtx, color: Color) -> Act {
        let inp = self.inp;
        let p = self.pos;
        let next = self.peek(p + 1);
        if ctx == DollarCtx::Inserted {
            match next {
                Some(c) if Self::is_var_start(c) => {}
                _ => return self.close_inserted(),
            }
        }
        match next {
            None => {
                self.put_n(color, 1);
                Act::Stay
            }
            Some(b'\'') => {
                if let DollarCtx::Dq { .. } = ctx {
                    self.put_n(color, 1);
                    Act::Stay
                } else {
                    self.put_n(Color::AnsiC, 2);
                    Act::Push(State::AnsiC)
                }
            }
            Some(b'"') => {
                self.put_n(color, 1);
                Act::Stay
            }
            Some(b'(') => {
                if self.peek(p + 2) == Some(b'(') {
                    self.put_n(Color::Magenta, 3);
                    Act::Push(State::Brackets { stack: vec![b')', b')'] })
                } else {
                    // The original looks for the closing parenthesis (and the
                    // byte after it) to recognize `$(pwd)`.
                    let complete = match self.closing_paren(p + 1) {
                        Some(e) => self.need_after(e),
                        None => false,
                    };
                    if inp[p..].starts_with(b"$(pwd)") && complete {
                        if let DollarCtx::Quote(end) = ctx {
                            self.open_inserted(end)
                        } else {
                            self.pwd_paren();
                            Act::Stay
                        }
                    } else if let DollarCtx::Quote(end) = ctx {
                        self.open_inserted(end)
                    } else {
                        self.put_n(Color::None, 2);
                        Act::Push(State::Normal { end: End::Paren, arm: false })
                    }
                }
            }
            Some(b'{') => self.dollar_brace(ctx, p),
            Some(c) if is_ident_start(c) => self.dollar_ident(ctx, p),
            Some(c) if c.is_ascii_digit() => {
                // Only the visible window is examined for further digits.
                let mut e = p + 2;
                while let Some(d) = self.vis(e) {
                    if !d.is_ascii_digit() {
                        break;
                    }
                    e += 1;
                }
                if e - (p + 1) >= 2 {
                    return Act::Err(ParseError::Pitfall { start: p, end: e });
                }
                if let DollarCtx::Quote(end) = ctx {
                    self.open_inserted(end)
                } else {
                    self.put_n(Color::Var, 2);
                    Act::Stay
                }
            }
            Some(b'@') | Some(b'-') => {
                if let DollarCtx::Quote(end) = ctx {
                    self.open_inserted(end)
                } else {
                    self.put_n(Color::Var, 2);
                    Act::Stay
                }
            }
            Some(b'*') => match ctx {
                DollarCtx::Quote(_) => {
                    self.insert(b"\"");
                    self.put_n(Color::Var, 1);
                    self.delete_n(Color::Var, 1);
                    self.insert(b"@");
                    self.insert(b"\"");
                    Act::Stay
                }
                DollarCtx::Inserted => {
                    self.put_n(Color::Var, 2);
                    self.close_inserted()
                }
                _ => {
                    self.put_n(Color::Var, 2);
                    Act::Stay
                }
            },
            Some(b'?') | Some(b'$') | Some(b'!') | Some(b'#') => {
                self.put_n(Color::Var, 2);
                Act::Stay
            }
            Some(_) => {
                self.put_n(color, 1);
                Act::Stay
            }
        }
    }

    fn dollar_ident(&mut self, ctx: DollarCtx, p: usize) -> Act {
        let inp = self.inp;
        match ctx {
            DollarCtx::Quote(end) => self.open_inserted(end),
            DollarCtx::Inserted => {
                let e = self.ident_end(p + 1);
                let braces = match self.peek(e) {
                    None => true,
                    Some(b'"') => match self.peek(e + 1) {
                        None => true,
                        Some(d) => is_ident(d),
                    },
                    _ => false,
                };
                if braces {
                    self.put_n(Color::Var, 1);
                    self.insert(b"{");
                    self.put_to(Color::Var, e);
                    self.insert(b"}");
                } else {
                    self.put_to(Color::Var, e);
                }
                Act::Stay
            }
            _ => {
                // Greedy, no lookahead needed.
                let mut e = p + 1;
                while e < inp.len() && is_ident(inp[e]) {
                    e += 1;
                }
                self.put_to(Color::Var, e);
                Act::Stay
            }
        }
    }

    fn dollar_brace(&mut self, ctx: DollarCtx, p: usize) -> Act {
        let inp = self.inp;
        let end = match self.brace_extent(p + 1) {
            Some(e) => e,
            None => {
                if let DollarCtx::Quote(end) = ctx {
                    return self.open_inserted(end);
                }
                let len = inp.len();
                self.put_to(Color::Var, len);
                return Act::Push(State::Unterminated);
            }
        };
        let content = &inp[p + 2..end - 1];
        let unquotable = Self::unquotable(content);
        let pure_ident = !content.is_empty()
            && is_ident_start(content[0])
            && content.iter().all(|&c| is_ident(c));
        if !unquotable {
            self.need_after(end);
        }
        match ctx {
            DollarCtx::Quote(qend) => {
                if unquotable {
                    self.put_to(Color::Var, end);
                    Act::Stay
                } else {
                    self.open_inserted(qend)
                }
            }
            DollarCtx::Inserted => {
                // ${name[*]} -> ${name[@]}
                let mut ne = 0;
                while ne < content.len() && is_ident(content[ne]) {
                    ne += 1;
                }
                if ne > 0
                    && is_ident_start(content[0])
                    && content.len() >= ne + 3
                    && &content[ne..ne + 3] == b"[*]"
                {
                    let star = p + 2 + ne + 1;
                    self.put_to(Color::Var, star);
                    self.delete_n(Color::Var, 1);
                    self.insert(b"@");
                    self.put_to(Color::Var, end);
                    return Act::Stay;
                }
                if pure_ident {
                    let keep = match self.at(end) {
                        None => true,
                        Some(c) if is_ident(c) => true,
                        Some(b'"') => self.at(end + 1).map_or(false, is_ident),
                        _ => false,
                    };
                    if !keep {
                        self.put_n(Color::Var, 1);
                        self.delete_n(Color::Var, 1);
                        self.put_to(Color::Var, end - 1);
                        self.delete_n(Color::Var, 1);
                        return Act::Stay;
                    }
                }
                self.put_to(Color::Var, end);
                Act::Stay
            }
            DollarCtx::Dq { at_start } => {
                if at_start
                    && pure_ident
                    && self.at(end) == Some(b'"')
                    && self.at(end + 1).map_or(false, |d| !is_ident(d))
                {
                    self.put_n(Color::Var, 1);
                    self.delete_n(Color::Var, 1);
                    self.put_to(Color::Var, end - 1);
                    self.delete_n(Color::Var, 1);
                } else {
                    self.put_to(Color::Var, end);
                }
                Act::Stay
            }
            DollarCtx::Plain => {
                self.put_to(Color::Var, end);
                Act::Stay
            }
        }
    }

    // ---------------------------------------------------------------
    // State steps
    // ---------------------------------------------------------------

    fn step(&mut self, st: &mut State) -> Act {
        let c = self.cur();
        match st {
            State::Normal { end, arm } => {
                let (end, arm) = (*end, *arm);
                if arm && c == b';' && self.peek(self.pos + 1) == Some(b';') {
                    self.put_n(Color::None, 2);
                    return Act::Pop;
                }
                if self.is_end(end) {
                    self.handle_end(end);
                    return Act::Pop;
                }
                match c {
                    b'#' => {
                        self.comment();
                        Act::Stay
                    }
                    b'(' => {
                        if self.peek(self.pos + 1) == Some(b'(') {
                            self.put_n(Color::Magenta, 2);
                            Act::Push(State::Brackets { stack: vec![b')', b')'] })
                        } else {
                            self.put_n(Color::None, 1);
                            Act::Push(State::Normal { end: End::Paren, arm: false })
                        }
                    }
                    b'\\' => self.escape(),
                    _ if c <= 0x20 || matches!(c, b';' | b'&' | b'|' | b'<' | b'>') => {
                        self.put_n(Color::None, 1);
                        Act::Stay
                    }
                    _ => Act::Replace(State::Command { end, arm, started: false }),
                }
            }
            State::Command { end, arm, started } => {
                let (end, arm) = (*end, *arm);
                if !*started {
                    *started = true;
                    if let Some(act) = self.command_start(end, arm) {
                        return act;
                    }
                }
                if self.is_end(end) {
                    self.handle_end(end);
                    return Act::Pop;
                }
                match c {
                    b'>' if self.peek(self.pos + 1) == Some(b'&') => {
                        self.put_n(Color::Cmd, 2);
                        Act::Stay
                    }
                    _ if c <= 0x20 => Act::Replace(State::Args { end, arm }),
                    b';' | b'&' | b'|' | b'(' => Act::Replace(State::Normal { end, arm }),
                    b'"' => self.start_dq(),
                    b'\'' => self.start_sq(),
                    b'\\' => self.escape(),
                    b'$' => self.dollar(DollarCtx::Quote(end), Color::Cmd),
                    b'`' => self.open_inserted(end),
                    _ => {
                        self.put_n(Color::Cmd, 1);
                        Act::Stay
                    }
                }
            }
            State::TestCmd { end, arm } => {
                let (end, arm) = (*end, *arm);
                self.test_cmd(end, arm)
            }
            State::Args { end, arm } => {
                let (end, arm) = (*end, *arm);
                self.args_char(end, arm)
            }
            State::Rvalue { end, arm } => {
                let (end, arm) = (*end, *arm);
                if self.is_end(end) {
                    self.handle_end(end);
                    return Act::Pop;
                }
                match c {
                    b'>' if self.peek(self.pos + 1) == Some(b'&') => {
                        self.put_n(Color::None, 2);
                        Act::Stay
                    }
                    _ if c <= 0x20 || matches!(c, b';' | b'&' | b'|') => {
                        Act::Replace(State::Normal { end, arm })
                    }
                    b'(' => {
                        self.put_n(Color::None, 1);
                        Act::Push(State::Array)
                    }
                    b'"' => self.start_dq(),
                    b'\'' => self.start_sq(),
                    b'\\' => self.escape(),
                    b'$' => self.dollar(DollarCtx::Plain, Color::None),
                    b'`' => self.plain_backtick(),
                    b'<' if self.peek(self.pos + 1) == Some(b'<') => self.heredoc(Color::None),
                    _ => {
                        self.put_n(Color::None, 1);
                        Act::Stay
                    }
                }
            }
            State::Array => match c {
                b')' => Act::Pop,
                b'#' => {
                    self.comment();
                    Act::Stay
                }
                b'"' => self.start_dq(),
                b'\'' => self.start_sq(),
                b'\\' => self.escape(),
                b'$' => self.dollar(DollarCtx::Quote(End::None), Color::None),
                b'`' => self.open_inserted(End::None),
                b'<' if self.peek(self.pos + 1) == Some(b'<') => self.heredoc(Color::None),
                _ => {
                    self.put_n(Color::None, 1);
                    Act::Stay
                }
            },
            State::Dq { at_start } => {
                let was_start = *at_start;
                *at_start = false;
                match c {
                    b'"' => {
                        self.put_n(Color::Dq, 1);
                        Act::Pop
                    }
                    b'\\' => self.escape(),
                    b'$' => self.dollar(DollarCtx::Dq { at_start: was_start }, Color::Dq),
                    b'`' => self.dq_backtick(),
                    _ => {
                        self.put_n(Color::Dq, 1);
                        Act::Stay
                    }
                }
            }
            State::Inserted { end } => match c {
                b'`' if matches!(end, End::Backtick { .. }) => self.close_inserted(),
                b'$' => self.dollar(DollarCtx::Inserted, Color::Dq),
                b'`' => self.dq_backtick(),
                b'"' => {
                    self.delete_n(Color::Dq, 1);
                    Act::Replace(State::Dq { at_start: true })
                }
                _ => {
                    let inp = self.inp;
                    let in_backtick = matches!(end, End::Backtick { .. });
                    let mut j = self.pos;
                    while j < inp.len() && is_absorbable(inp[j]) {
                        j += 1;
                    }
                    self.touch(j);
                    if j < inp.len()
                        && matches!(inp[j], b'$' | b'"' | b'`')
                        && j > self.pos
                        && !(in_backtick && inp[j] == b'`')
                        && self.absorb_ok(j)
                    {
                        self.put_to(Color::Dq, j);
                        Act::Stay
                    } else {
                        self.close_inserted()
                    }
                }
            },
            State::Sq => {
                if c == b'\'' {
                    self.put_n(Color::Sq, 1);
                    Act::Pop
                } else {
                    self.put_n(Color::Sq, 1);
                    Act::Stay
                }
            }
            State::AnsiC => match c {
                b'\'' => {
                    self.put_n(Color::AnsiC, 1);
                    Act::Pop
                }
                b'\\' => self.escape(),
                _ => {
                    self.put_n(Color::AnsiC, 1);
                    Act::Stay
                }
            },
            State::Brackets { stack } => match c {
                b'(' | b'[' => {
                    stack.push(if c == b'(' { b')' } else { b']' });
                    self.put_n(Color::Magenta, 1);
                    Act::Stay
                }
                b')' | b']' => {
                    if stack.last() == Some(&c) {
                        stack.pop();
                    }
                    self.put_n(Color::Magenta, 1);
                    if stack.is_empty() {
                        Act::Pop
                    } else {
                        Act::Stay
                    }
                }
                b'"' => self.start_dq(),
                b'\'' => self.start_sq(),
                b'\\' => self.escape(),
                b'$' => self.dollar(DollarCtx::Plain, Color::Magenta),
                b'`' => self.plain_backtick(),
                b'<' if self.peek(self.pos + 1) == Some(b'<') => self.heredoc(Color::Magenta),
                _ => {
                    self.put_n(Color::Magenta, 1);
                    Act::Stay
                }
            },
            State::CaseHead { after_ws } => {
                let ws = *after_ws;
                *after_ws = false;
                match c {
                    b'#' => {
                        self.comment();
                        Act::Stay
                    }
                    b'i' if ws
                        && self.peek(self.pos + 1) == Some(b'n')
                        && !self.peek(self.pos + 2).map_or(false, is_ident) =>
                    {
                        self.put_n(Color::Bold, 2);
                        Act::Replace(State::CaseBody)
                    }
                    b'"' => self.start_dq(),
                    b'\'' => self.start_sq(),
                    b'\\' => self.escape(),
                    b'$' => self.dollar(DollarCtx::Plain, Color::Bold),
                    b'`' => self.plain_backtick(),
                    b' ' | b'\t' | b'\n' => {
                        *after_ws = true;
                        self.put_n(Color::Bold, 1);
                        Act::Stay
                    }
                    _ => {
                        self.put_n(Color::Bold, 1);
                        Act::Stay
                    }
                }
            }
            State::CaseBody => {
                match c {
                    b')' => {
                        self.put_n(Color::None, 1);
                        return Act::Push(State::Normal { end: End::None, arm: true });
                    }
                    b'#' => {
                        self.comment();
                        return Act::Stay;
                    }
                    b'"' => return self.start_dq(),
                    b'\'' => return self.start_sq(),
                    b'\\' => return self.escape(),
                    b'$' => return self.dollar(DollarCtx::Plain, Color::None),
                    b'`' => return self.plain_backtick(),
                    b'<' if self.peek(self.pos + 1) == Some(b'<') => {
                        return self.heredoc(Color::None)
                    }
                    _ if c <= 0x20 || matches!(c, b'(' | b'|' | b';' | b'&') => {
                        self.put_n(Color::None, 1);
                        return Act::Stay;
                    }
                    _ => {}
                }
                // A word: the original needs to see its end.
                let inp = self.inp;
                let mut j = self.pos;
                while j < inp.len()
                    && !(inp[j] <= 0x20 || matches!(inp[j], b'(' | b')' | b'|' | b';' | b'&'))
                {
                    j += 1;
                }
                self.touch(j);
                if c == b'e'
                    && inp[self.pos..].starts_with(b"esac")
                    && !self.at(self.pos + 4).map_or(false, is_ident)
                    && (self.pos == 0 || !is_ident(inp[self.pos - 1]))
                {
                    self.put_n(Color::Bold, 4);
                    return Act::Pop;
                }
                self.put_n(Color::None, 1);
                Act::Stay
            }
            State::ForVar { end, arm } => {
                let (end, arm) = (*end, *arm);
                match c {
                    b' ' | b'\t' => {
                        self.put_n(Color::Bold, 1);
                        Act::Stay
                    }
                    b'\n' | b';' | b'&' | b'|' | b')' => Act::Pop,
                    b'#' => {
                        self.comment();
                        Act::Stay
                    }
                    b'(' if self.peek(self.pos + 1) == Some(b'(') => {
                        self.put_n(Color::Magenta, 2);
                        Act::Push(State::Brackets { stack: vec![b')', b')'] })
                    }
                    b'i' if self.peek(self.pos + 1) == Some(b'n')
                        && !self.peek(self.pos + 2).map_or(false, is_ident) =>
                    {
                        self.put_n(Color::None, 2);
                        Act::Push(State::ForIn { first: true })
                    }
                    _ => {
                        let inp = self.inp;
                        let i = self.ident_end(self.pos);
                        let term = match inp.get(i) {
                            None => true,
                            Some(&t) => t <= 0x20 || matches!(t, b';' | b'&' | b'|' | b')' | b'#'),
                        };
                        if i > self.pos && term {
                            self.put_to(Color::Assign, i);
                            Act::Stay
                        } else {
                            self.put_to(Color::Assign, i);
                            Act::Replace(State::Command { end, arm, started: true })
                        }
                    }
                }
            }
            State::ForIn { first } => {
                match c {
                    b'>' if self.peek(self.pos + 1) == Some(b'&') => {
                        *first = false;
                        self.put_n(Color::None, 2);
                        return Act::Stay;
                    }
                    b'\n' | b';' | b'&' | b'|' => return Act::Pop,
                    b'#' => {
                        self.comment();
                        return Act::Stay;
                    }
                    _ if c <= 0x20 => {
                        self.put_n(Color::None, 1);
                        return Act::Stay;
                    }
                    _ => {}
                }
                let was_first = *first;
                *first = false;
                match c {
                    b'$' => {
                        if was_first {
                            let inp = self.inp;
                            if let Some(n) = self.peek(self.pos + 1) {
                                if is_ident_start(n) {
                                    let e = self.ident_end(self.pos + 1);
                                    let mut k = e;
                                    while k < inp.len() && inp[k] == b' ' {
                                        k += 1;
                                    }
                                    if matches!(self.peek(k), Some(b';') | Some(b'\n')) {
                                        self.insert(b"\"");
                                        self.put_n(Color::Var, 1);
                                        self.insert(b"{");
                                        self.put_to(Color::Var, e);
                                        self.insert(b"[@]}\"");
                                        return Act::Pop;
                                    }
                                }
                            }
                        }
                        self.dollar(DollarCtx::Quote(End::None), Color::None)
                    }
                    b'"' => self.start_dq(),
                    b'\'' => self.start_sq(),
                    b'\\' => self.escape(),
                    b'`' => self.open_inserted(End::None),
                    b'<' if self.peek(self.pos + 1) == Some(b'<') => self.heredoc(Color::None),
                    _ => {
                        self.put_n(Color::None, 1);
                        Act::Stay
                    }
                }
            }
            State::XHack { rx, end, arm } => {
                let (rx, end, arm) = (*rx, *end, *arm);
                if self.pos == rx {
                    self.delete_n(Color::None, 1);
                    let empty = match self.peek(self.pos) {
                        None => true,
                        Some(b'`') => true,
                        Some(c) => is_kw_term(c),
                    };
                    if empty {
                        self.insert(b"\"\"");
                    }
                    return Act::Pop;
                }
                self.args_char(end, arm)
            }
            State::TestArg { suffix, done, end } => {
                let end = *end;
                if *done {
                    let suffix = *suffix;
                    self.insert(suffix);
                    return Act::Pop;
                }
                *done = true;
                match c {
                    b'"' => self.start_dq(),
                    b'\'' => self.start_sq(),
                    b'\\' => self.escape(),
                    b'`' => self.open_inserted(end),
                    b'$' => self.dollar(DollarCtx::Quote(end), Color::None),
                    _ => {
                        self.put_n(Color::None, 1);
                        Act::Stay
                    }
                }
            }
            State::Heredoc { delim, dash } => {
                let delim = std::mem::take(delim);
                let dash = *dash;
                let act = self.step_heredoc(&delim, dash);
                if let State::Heredoc { delim: d, .. } = st {
                    *d = delim;
                }
                act
            }
            State::Unterminated => {
                // Should not be stepped; consume to end.
                let len = self.inp.len();
                self.put_to(Color::None, len);
                Act::Stay
            }
        }
    }

    /// One step of the argument list state.
    fn args_char(&mut self, end: End, arm: bool) -> Act {
        if self.is_end(end) {
            self.handle_end(end);
            return Act::Pop;
        }
        let c = self.cur();
        match c {
            b'>' if self.peek(self.pos + 1) == Some(b'&') => {
                self.put_n(Color::None, 2);
                Act::Stay
            }
            b'\n' | b';' | b'&' | b'|' => Act::Replace(State::Normal { end, arm }),
            b'#' => {
                self.comment();
                Act::Stay
            }
            b'"' => self.start_dq(),
            b'\'' => self.start_sq(),
            b'\\' => self.escape(),
            b'$' => self.dollar(DollarCtx::Quote(end), Color::None),
            b'`' => self.open_inserted(end),
            b'<' if self.peek(self.pos + 1) == Some(b'<') => self.heredoc(Color::None),
            b'<' | b'>' => {
                self.peek(self.pos + 1);
                self.put_n(Color::None, 1);
                Act::Stay
            }
            _ => {
                self.put_n(Color::None, 1);
                Act::Stay
            }
        }
    }

    /// Lookahead right after `[ ` or `test `: `-n`/`-z` arguments and the
    /// `x"$a" = xb` idiom are rewritten.
    fn test_cmd(&mut self, end: End, arm: bool) -> Act {
        let inp = self.inp;
        let k = self.pos;
        let suffix: Option<&'static [u8]> = if inp[k..].starts_with(b"-n ") {
            Some(b" != \"\"")
        } else if inp[k..].starts_with(b"-z ") {
            Some(b" = \"\"")
        } else {
            None
        };
        if inp.get(k) == Some(&b'-') {
            self.peek(k + 1);
            self.peek(k + 2);
        }
        if let Some(suffix) = suffix {
            if self.test_unit_ok(k + 3) {
                self.delete_n(Color::None, 3);
                return Act::ReplacePush(
                    State::Args { end, arm },
                    State::TestArg { suffix, done: false, end },
                );
            }
        }
        if inp.get(k) == Some(&b'x') {
            if let Some(e) = self.unit_extent(k + 1) {
                if self.peek(e) == Some(b' ') {
                    let oplen = match self.peek(e + 1) {
                        Some(b'=') => match self.peek(e + 2) {
                            Some(b' ') => Some(2),
                            Some(b'=') => {
                                if self.peek(e + 3) == Some(b' ') { Some(3) } else { None }
                            }
                            _ => None,
                        },
                        Some(b'!') => {
                            if self.peek(e + 2) == Some(b'=') && self.peek(e + 3) == Some(b' ') {
                                Some(3)
                            } else {
                                None
                            }
                        }
                        _ => None,
                    };
                    if let Some(oplen) = oplen {
                        let rx = e + 1 + oplen;
                        if self.peek(rx) == Some(b'x') {
                            self.delete_n(Color::None, 1);
                            return Act::ReplacePush(
                                State::Args { end, arm },
                                State::XHack { rx, end, arm },
                            );
                        }
                    }
                }
            }
        }
        Act::Replace(State::Args { end, arm })
    }

    /// Checks done at the start of a command word: assignments and keywords.
    fn command_start(&mut self, end: End, arm: bool) -> Option<Act> {
        let inp = self.inp;
        let p = self.pos;
        let c = inp[p];
        // Assignment?
        if is_ident_start(c) {
            let mut i = self.ident_end(p);
            let mut ok = true;
            while ok && inp.get(i) == Some(&b'[') {
                let mut j = i + 1;
                loop {
                    match inp.get(j) {
                        None => {
                            self.touch_eof();
                            ok = false;
                            break;
                        }
                        Some(b'\\') => {
                            self.touch(j);
                            ok = false;
                            break;
                        }
                        Some(b']') => {
                            self.touch(j + 1);
                            i = j + 1;
                            break;
                        }
                        _ => j += 1,
                    }
                }
            }
            if ok {
                if inp.get(i) == Some(&b'=') {
                    self.put_to(Color::Assign, i);
                    self.put_n(Color::None, 1);
                    return Some(Act::Replace(State::Rvalue { end, arm }));
                }
                if inp.get(i) == Some(&b'+') && inp.get(i + 1) == Some(&b'=') {
                    self.peek(i + 1);
                    self.put_to(Color::Assign, i);
                    self.put_n(Color::None, 2);
                    return Some(Act::Replace(State::Rvalue { end, arm }));
                }
            }
        }
        // Keyword?
        let mut j = p;
        while j < inp.len() {
            let d = inp[j];
            if is_kw_term(d) || matches!(d, b'"' | b'\'' | b'$' | b'`' | b'\\' | b'=') {
                break;
            }
            j += 1;
        }
        self.touch(j);
        let word = &inp[p..j];
        let term_ok = j == inp.len() || is_kw_term(inp[j]);
        if !term_ok {
            return None;
        }
        match word {
            b"if" | b"then" | b"elif" | b"else" | b"fi" | b"do" | b"done" | b"while" | b"until"
            | b"function" | b"declare" | b"local" | b"export" | b"readonly" | b"{" | b"}"
            | b"!" => {
                self.put_to(Color::Bold, j);
                Some(Act::Replace(State::Normal { end, arm }))
            }
            b"for" | b"select" => {
                self.put_to(Color::Bold, j);
                match inp.get(j) {
                    None => Some(Act::ReplacePush(
                        State::Normal { end, arm },
                        State::ForVar { end, arm },
                    )),
                    Some(b' ') | Some(b'\t') => {
                        let mut k = j;
                        while matches!(inp.get(k), Some(b' ') | Some(b'\t')) {
                            k += 1;
                        }
                        self.put_to(Color::Bold, k);
                        Some(Act::ReplacePush(
                            State::Normal { end, arm },
                            State::ForVar { end, arm },
                        ))
                    }
                    _ => Some(Act::Replace(State::Normal { end, arm })),
                }
            }
            b"case" => {
                self.put_to(Color::Bold, j);
                Some(Act::ReplacePush(
                    State::Normal { end, arm },
                    State::CaseHead { after_ws: true },
                ))
            }
            b"[[" => {
                if j == inp.len() || inp[j] <= 0x20 {
                    self.put_to(Color::Magenta, j);
                    Some(Act::ReplacePush(
                        State::Normal { end, arm },
                        State::Brackets { stack: vec![b']', b']'] },
                    ))
                } else {
                    None
                }
            }
            b"esac" if arm => {
                self.insert(b";; ");
                Some(Act::Pop)
            }
            b"[" | b"test" => {
                // The following space is included if what follows it is not
                // another space (judged within the visible window).
                if inp.get(j) == Some(&b' ') && self.vis(j + 1) != Some(b' ') {
                    self.put_to(Color::Cmd, j + 1);
                    Some(Act::Replace(State::TestCmd { end, arm }))
                } else {
                    self.put_to(Color::Cmd, j);
                    Some(Act::Replace(State::Args { end, arm }))
                }
            }
            _ => None,
        }
    }
}

/// Whether a state may silently end at end of file.
fn eof_ok(st: &State) -> bool {
    match st {
        State::Normal { end: End::None, .. }
        | State::Command { end: End::None, .. }
        | State::TestCmd { end: End::None, .. }
        | State::Args { end: End::None, .. }
        | State::Rvalue { end: End::None, .. } => true,
        _ => false,
    }
}

fn run(inp: &[u8], out: Out) -> (Out, Result<(), ParseError>) {
    let mut m = Machine { inp, pos: 0, out, ws: 0, step_start: 0 };
    let mut stack: Vec<State> = vec![State::Normal { end: End::None, arm: false }];
    loop {
        if m.pos >= inp.len() {
            // End of file: unwind what can be unwound.
            loop {
                if stack.len() <= 1 {
                    return (m.out, Ok(()));
                }
                let top = stack.last().unwrap();
                match top {
                    State::Inserted { .. } => {
                        m.insert(b"\"");
                        stack.pop();
                    }
                    State::TestArg { suffix, done: true, .. } => {
                        let suffix = *suffix;
                        m.insert(suffix);
                        stack.pop();
                    }
                    s if eof_ok(s) => {
                        stack.pop();
                    }
                    _ => return (m.out, Err(ParseError::Eof)),
                }
            }
        }
        m.step_start = m.pos;
        let act = {
            let top = stack.last_mut().unwrap();
            m.step(top)
        };
        match act {
            Act::Stay => {}
            Act::Push(s) => stack.push(s),
            Act::Pop => {
                stack.pop();
                if stack.is_empty() {
                    stack.push(State::Normal { end: End::None, arm: false });
                }
            }
            Act::Replace(s) => {
                stack.pop();
                stack.push(s);
            }
            Act::ReplacePush(a, b) => {
                stack.pop();
                stack.push(a);
                stack.push(b);
            }
            Act::Err(e) => return (m.out, Err(e)),
        }
    }
}

